import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    if n <= 1:
        return edge_distance.copy()
    tour = np.asarray(local_opt_tour, dtype=int)
    mask = ~np.eye(n, dtype=bool)
    mean_dist = edge_distance[mask].mean() if n > 1 else 1.0
    if mean_dist <= 0:
        mean_dist = 1.0
    penalty = 0.1 * mean_dist

    edges = []
    seen = set()
    for i in range(n):
        u = tour[i]
        v = tour[(i + 1) % n]
        if u == v:
            continue
        e = (u, v) if u < v else (v, u)
        if e not in seen:
            seen.add(e)
            edges.append(e)

    if not edges:
        return edge_distance.copy()

    utilities = np.array([
        edge_distance[u, v] / (1.0 + edge_n_used[u, v])
        for u, v in edges
    ])
    avg_util = utilities.mean()

    for (u, v), util in zip(edges, utilities):
        if util >= avg_util:
            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    updated_edge_distance = edge_distance + penalty * edge_n_used
    return updated_edge_distance
